"""Merge overlapping or touching numeric intervals."""


def merge_intervals(items):
    """Merge overlapping or touching [start, end] pairs.

    Returns a new sorted list of non-overlapping [start, end] lists.
    The input is not mutated. Reversed endpoints raise ValueError.
    """
    pairs = []
    for item in items:
        if len(item) != 2:
            raise ValueError("each interval must have exactly two endpoints: %r" % (item,))
        start, end = item[0], item[1]
        if start > end:
            raise ValueError("reversed interval: %r" % (item,))
        pairs.append((start, end))
    pairs.sort()
    merged = []
    for start, end in pairs:
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged

