import copy
import unittest

from intervals import merge_intervals


class MergeIntervalsTest(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(merge_intervals([]), [])

    def test_single(self):
        self.assertEqual(merge_intervals([[1, 3]]), [[1, 3]])

    def test_overlapping(self):
        self.assertEqual(merge_intervals([[1, 3], [2, 6], [8, 10]]), [[1, 6], [8, 10]])

    def test_touching_merge(self):
        self.assertEqual(merge_intervals([[1, 2], [2, 3]]), [[1, 3]])

    def test_disjoint_stay_separate(self):
        self.assertEqual(merge_intervals([[5, 6], [1, 2]]), [[1, 2], [5, 6]])

    def test_unsorted_input_sorted_output(self):
        self.assertEqual(merge_intervals([[8, 10], [1, 4], [3, 5]]), [[1, 5], [8, 10]])

    def test_contained(self):
        self.assertEqual(merge_intervals([[1, 10], [2, 3], [4, 5]]), [[1, 10]])

    def test_point_intervals(self):
        self.assertEqual(merge_intervals([[3, 3], [3, 3], [1, 1]]), [[1, 1], [3, 3]])

    def test_floats_and_negatives(self):
        self.assertEqual(merge_intervals([[-2.5, 0], [0, 1.5], [2, 3]]), [[-2.5, 1.5], [2, 3]])

    def test_tuples_accepted(self):
        self.assertEqual(merge_intervals([(1, 2), (2, 4)]), [[1, 4]])

    def test_reversed_raises(self):
        with self.assertRaises(ValueError):
            merge_intervals([[1, 2], [5, 3]])

    def test_does_not_mutate(self):
        data = [[5, 7], [1, 3], [2, 4]]
        before = copy.deepcopy(data)
        result = merge_intervals(data)
        self.assertEqual(data, before)
        result[0][0] = 99
        self.assertEqual(data, before)

    def test_result_is_new_lists(self):
        data = [[1, 2]]
        result = merge_intervals(data)
        self.assertIsNot(result[0], data[0])


if __name__ == "__main__":
    unittest.main()
